-- Draft-only service and calendar examples. No SLA commitments or holidays are invented.
INSERT OR IGNORE INTO sd_service_catalog(id,reference,country_code,name,category,state,customer_visible,data) SELECT 'starter-service-INC-'||code,'HMT-'||code||'-SVC-INC',code,'Infrastructure incident support','Infrastructure','draft',1,'{"request_type": "incident", "funding_modes": ["sla", "billable"], "sla_entitlement_ids": [], "required_fields": ["business_impact"], "questions": [{"key": "q_environment", "label": "Affected environment", "type": "select", "required": true, "options": ["Production", "Disaster recovery", "Test", "Development"]}], "description_template": "Describe the symptoms, affected users and when the issue began.", "approval_required": false, "default_owner_id": "", "approver_id": "", "subcategory": "", "guidance": "Starter draft: confirm service scope, actual contract SLA coverage, routing and approval responsibilities before publication."}' FROM countries WHERE code IN ('MU','MG','RW','BI');
INSERT OR IGNORE INTO sd_service_catalog(id,reference,country_code,name,category,state,customer_visible,data) SELECT 'starter-service-REQ-'||code,'HMT-'||code||'-SVC-REQ',code,'Standard IT service assistance','Service request','draft',1,'{"request_type": "service_request", "funding_modes": ["sla", "billable"], "sla_entitlement_ids": [], "required_fields": ["business_impact"], "questions": [{"key": "q_outcome", "label": "Required outcome", "type": "textarea", "required": true, "options": []}], "description_template": "Describe the requested assistance, affected system and success criteria.", "approval_required": false, "default_owner_id": "", "approver_id": "", "subcategory": "", "guidance": "Starter draft: confirm service scope, actual contract SLA coverage, routing and approval responsibilities before publication."}' FROM countries WHERE code IN ('MU','MG','RW','BI');
INSERT OR IGNORE INTO sd_service_catalog(id,reference,country_code,name,category,state,customer_visible,data) SELECT 'starter-service-CHG-'||code,'HMT-'||code||'-SVC-CHG',code,'Controlled infrastructure change','Change enablement','draft',1,'{"request_type": "change", "funding_modes": ["sla", "billable"], "sla_entitlement_ids": [], "required_fields": ["business_impact", "asset_name"], "questions": [{"key": "q_window", "label": "Requested maintenance window", "type": "text", "required": true, "options": []}, {"key": "q_rollback", "label": "Rollback approach", "type": "textarea", "required": true, "options": []}], "description_template": "Describe the planned change, affected assets, validation and implementation risks.", "approval_required": true, "default_owner_id": "", "approver_id": "", "subcategory": "", "guidance": "Starter draft: confirm service scope, actual contract SLA coverage, routing and approval responsibilities before publication."}' FROM countries WHERE code IN ('MU','MG','RW','BI');
INSERT OR IGNORE INTO sd_business_calendars(id,country_code,name,timezone,data,active) SELECT 'starter-calendar-'||code,code,'Draft business-hours example — confirm agreed support hours',CASE code WHEN 'MU' THEN 'Indian/Mauritius' WHEN 'MG' THEN 'Indian/Antananarivo' WHEN 'RW' THEN 'Africa/Kigali' ELSE 'Africa/Bujumbura' END,'{"week": {"0": [], "1": [["09:00", "17:00"]], "2": [["09:00", "17:00"]], "3": [["09:00", "17:00"]], "4": [["09:00", "17:00"]], "5": [["09:00", "17:00"]], "6": []}, "holidays": [], "overrides": {}}',0 FROM countries WHERE code IN ('MU','MG','RW','BI');
INSERT INTO sd_catalog_audit(id,country_code,entity_type,entity_id,action,snapshot) SELECT lower(hex(randomblob(16))),country_code,'service',id,'Starter service draft prepared',json_object('reference',reference,'state','draft','prepared_by','Assistant on user instruction') FROM sd_service_catalog s WHERE id LIKE 'starter-service-%' AND NOT EXISTS(SELECT 1 FROM sd_catalog_audit a WHERE a.entity_id=s.id AND a.action='Starter service draft prepared');
INSERT INTO sd_catalog_audit(id,country_code,entity_type,entity_id,action,snapshot) SELECT lower(hex(randomblob(16))),country_code,'calendar',id,'Starter calendar example prepared',json_object('active',0,'holiday_dates','Not configured; confirm actual dates','prepared_by','Assistant on user instruction') FROM sd_business_calendars c WHERE id LIKE 'starter-calendar-%' AND NOT EXISTS(SELECT 1 FROM sd_catalog_audit a WHERE a.entity_id=c.id AND a.action='Starter calendar example prepared');
